-- ============================================
-- LUMA — Enrichissement Thématique 6 (Colocation) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"roommate": "ta coloc Mia"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "I''m honestly getting frustrated, it feels like I''m doing all the cleaning lately.", "text_fr": "Honnêtement je commence à être frustrée, j''ai l''impression de faire tout le ménage ces derniers temps.", "choices": [{"text": "You''re right, I''ve been slacking, I''m sorry.", "next": "n2"}, {"text": "I didn''t realize that, can we talk about it calmly?", "next": "n2b"}, {"text": "I actually think I''ve been doing my fair share too.", "next": "n2c"}]}, "n2": {"speaker": "roommate", "text": "I appreciate you owning that. Let''s make a clearer schedule.", "text_fr": "J''apprécie que tu le reconnaisses. Faisons un planning plus clair.", "choices": [{"text": "Agreed, let''s write one up together tonight.", "next": "n3"}]}, "n2b": {"speaker": "roommate", "text": "Yes, I''d like that, I don''t want this to become resentment.", "text_fr": "Oui, j''aimerais ça, je ne veux pas que ça devienne du ressentiment.", "choices": [{"text": "Neither do I, let''s fix this together.", "next": "n3"}]}, "n2c": {"speaker": "roommate", "text": "(surprised) Really? I genuinely don''t see it that way, can you show me?", "text_fr": "(surprise) Vraiment ? Je ne le vois vraiment pas comme ça, tu peux me montrer ?", "choices": [{"text": "Let''s actually track it for a week and compare notes.", "next": "n3b"}]}, "n3": {"speaker": "roommate", "text": "Thanks for hearing me out, I feel better already.", "text_fr": "Merci de m''avoir écoutée, je me sens déjà mieux.", "choices": [{"text": "I''m glad, we''re a good team.", "next": "n4"}]}, "n3b": {"speaker": "roommate", "text": "That''s a fair way to settle this without pointing fingers.", "text_fr": "C''est une façon juste de régler ça sans pointer du doigt.", "choices": [{"text": "Exactly, let''s see what the data actually shows.", "next": "n4"}]}, "n4": {"speaker": "roommate", "text": "(a week later) Okay, I see now it was more balanced than I thought — sorry for jumping to conclusions.", "text_fr": "(une semaine plus tard) D''accord, je vois maintenant que c''était plus équilibré que je pensais — désolée d''avoir tiré des conclusions hâtives.", "choices": [{"text": "No worries, I''m glad we cleared it up together.", "next": "end_resolved"}, {"text": "It''s okay, communication like this actually brought us closer.", "next": "end_closer"}]}, "end_resolved": {"speaker": "roommate", "text": "We really are. Let''s keep communicating like this.", "text_fr": "C''est vrai. Continuons à communiquer comme ça.", "end": true, "ending_label": "Tension résolue en profondeur 💙"}, "end_closer": {"speaker": "roommate", "text": "It really did. I''m glad we can be this honest with each other.", "text_fr": "C''est vrai. Je suis contente qu''on puisse être aussi honnêtes l''un envers l''autre.", "end": true, "ending_label": "Amitié renforcée par le conflit 🤝"}}}'::jsonb, is_playable = true
where title = 'Une tension qui dégénère et se résout'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"roommate": "ton coloc Leo"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "Want to throw a party this Saturday? It''s been a while.", "text_fr": "Ça te dit d''organiser une fête samedi ? Ça fait longtemps.", "choices": [{"text": "Sure, but let''s warn the neighbors in advance.", "next": "n2"}, {"text": "I''m a bit worried about the mess afterward, honestly.", "next": "n2b"}, {"text": "Let''s keep it small, just a few close friends.", "next": "n2c"}]}, "n2": {"speaker": "roommate", "text": "Good call, I''ll drop a note in their mailboxes.", "text_fr": "Bonne idée, je vais mettre un mot dans leurs boîtes aux lettres.", "choices": [{"text": "Perfect, let''s plan it then.", "next": "n3"}]}, "n2b": {"speaker": "roommate", "text": "Fair point, let''s agree we both clean up together after.", "text_fr": "Bon point, mettons-nous d''accord pour nettoyer ensemble après.", "choices": [{"text": "Deal, that makes me feel better about it.", "next": "n3"}]}, "n2c": {"speaker": "roommate", "text": "That works too, less chaos to manage.", "text_fr": "Ça marche aussi, moins de chaos à gérer.", "choices": [{"text": "Exactly, quality over quantity.", "next": "n3"}]}, "n3": {"speaker": "roommate", "text": "(the party happens, and it gets bigger than planned) Uh oh, word got around and more people showed up than expected!", "text_fr": "(la fête a lieu, et elle devient plus grande que prévu) Oh oh, le mot s''est passé et plus de monde est venu que prévu !", "choices": [{"text": "Let''s just manage it calmly, make sure everyone''s respectful.", "next": "n4"}, {"text": "We should probably start asking some people to leave.", "next": "n4b"}]}, "n4": {"speaker": "roommate", "text": "Good call, staying calm kept things under control.", "text_fr": "Bon réflexe, rester calme a permis de garder le contrôle.", "choices": [{"text": "Glad we handled it without drama.", "next": "n5"}]}, "n4b": {"speaker": "roommate", "text": "Yeah, it did get a bit too crowded for comfort — good thinking.", "text_fr": "Ouais, c''était un peu trop bondé pour être confortable — bien vu.", "choices": [{"text": "Better safe than dealing with bigger problems later.", "next": "n5"}]}, "n5": {"speaker": "roommate", "text": "(next morning) Well, that got a bit wild! Ready to clean up together like we planned?", "text_fr": "(le lendemain matin) Eh bien, ça a un peu dérapé ! Prêt à nettoyer ensemble comme prévu ?", "choices": [{"text": "Absolutely, teamwork makes it go fast.", "next": "end_cleaned"}]}, "end_cleaned": {"speaker": "roommate", "text": "Worth it though! Same time next month?", "text_fr": "Ça valait le coup quand même ! Même heure le mois prochain ?", "end": true, "ending_label": "Fête réussie, conséquences bien gérées 🎉"}}}'::jsonb, is_playable = true
where title = 'Organiser une fête et gérer les conséquences'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"roommate1": "coloc 1", "roommate2": "coloc 2"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate1", "text": "So, the move is in two weeks. Who''s handling the moving truck?", "text_fr": "Alors, le déménagement est dans deux semaines. Qui s''occupe du camion ?", "choices": [{"text": "I can book it, I know a good rental place.", "next": "n2"}, {"text": "Should we hire professional movers instead, to save time?", "next": "n2b"}]}, "n2": {"speaker": "roommate2", "text": "Great, I''ll handle packing the kitchen stuff then.", "text_fr": "Super, je vais m''occuper d''emballer la cuisine alors.", "choices": [{"text": "Perfect, I''ll take care of the living room.", "next": "n3"}]}, "n2b": {"speaker": "roommate2", "text": "That could work, but it''s a bigger budget hit — let''s compare costs first.", "text_fr": "Ça pourrait marcher, mais c''est un budget plus important — comparons les coûts d''abord.", "choices": [{"text": "Good idea, let''s get quotes from both options tonight.", "next": "n3b"}]}, "n3": {"speaker": "roommate1", "text": "Sounds like we''ve got a solid plan. Let''s make a shared checklist too.", "text_fr": "On dirait qu''on a un bon plan. Faisons aussi une liste partagée.", "choices": [{"text": "Good idea, I''ll set that up tonight.", "next": "n4"}]}, "n3b": {"speaker": "roommate1", "text": "(after comparing) The truck rental is way cheaper, let''s go with that.", "text_fr": "(après comparaison) La location de camion est bien moins chère, allons avec ça.", "choices": [{"text": "Agreed, and we''ll have more control over the schedule too.", "next": "n4"}]}, "n4": {"speaker": "roommate2", "text": "(moving day arrives) The truck is smaller than I expected — will everything fit?", "text_fr": "(jour du déménagement) Le camion est plus petit que prévu — est-ce que tout va rentrer ?", "choices": [{"text": "Let''s pack strategically, heavy items first, then fill the gaps.", "next": "n5"}, {"text": "We might need a second trip, let''s not stress about it.", "next": "n5b"}]}, "n5": {"speaker": "roommate2", "text": "Great thinking, everything actually fit perfectly!", "text_fr": "Bien pensé, tout est finalement rentré parfaitement !", "choices": [{"text": "Teamwork and good planning, as always.", "next": "end_organized"}]}, "n5b": {"speaker": "roommate1", "text": "You''re right, no need to panic, we''ll figure it out.", "text_fr": "Tu as raison, pas la peine de paniquer, on va se débrouiller.", "choices": [{"text": "Exactly, one trip at a time.", "next": "end_relaxed"}]}, "end_organized": {"speaker": "roommate2", "text": "This is going to go so much smoother with a plan like this.", "text_fr": "Ça va être bien plus fluide avec un plan comme ça.", "end": true, "ending_label": "Déménagement parfaitement organisé 📦"}, "end_relaxed": {"speaker": "roommate1", "text": "Sometimes flexibility beats perfect planning anyway.", "text_fr": "Parfois la flexibilité vaut mieux qu''une planification parfaite de toute façon.", "end": true, "ending_label": "Déménagement géré avec sérénité 😌"}}}'::jsonb, is_playable = true
where title = 'Un déménagement collectif à planifier'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
